)
$script:hvLiteralResults=foreach($case in $script:hvCases) {
 try { $null=[scriptblock]::Create($script:hvVerifyCode); $state='CompiledUnexpectedly' }
 catch { $state='BlockedByParseError' }
 [pscustomobject]@{Id=$case.Id;Expected=$case.Expected;Status=$state;BehaviorTestExecuted=$false}
}
$matchLine=($script:hvVerifyCode -split '\r?\n' | Where-Object {$_ -match '^\$m = '})
$script:hvPattern=[regex]::Matches($matchLine,"'([^']*)'")[0].Groups[1].Value
$script:hvPredicateResults=foreach($case in $script:hvCases) {
 $root=if($case.Install){$case.Install}else{'C:\ProgramData\McpServer'}
 $expectedExe=[IO.Path]::GetFullPath((Join-Path $root 'McpServer.Support.Mcp.exe'))
 $m=[regex]::Match($case.ImagePath.Trim(),$script:hvPattern,'IgnoreCase')
 $accepted=$m.Success
 if($accepted){$accepted=[IO.Path]::GetFullPath($m.Groups['exe'].Value).Equals($expectedExe,[StringComparison]::OrdinalIgnoreCase) -and $m.Groups['urls'].Value.Equals('http://+:7147',[StringComparison]::OrdinalIgnoreCase)}
 [pscustomobject]@{Id=$case.Id;Expected=$case.Expected;Accepted=$accepted;Pass=($accepted -eq $case.Expected);ImagePath=$case.ImagePath;Scope='Extracted regex plus exe and URL comparisons only'}
}
$script:hvPredicateResults | ConvertTo-Json -Depth 4
[pscustomobject]@{LiteralCases=$script:hvLiteralResults.Count;LiteralBehaviorExecuted=0;LiteralParseBlocked=$script:hvLiteralResults.Count;IsolatedPredicatePass=@($script:hvPredicateResults|Where-Object Pass).Count;IsolatedPredicateFail=@($script:hvPredicateResults|Where-Object {-not $_.Pass}).Count;Pattern=$script:hvPattern}|ConvertTo-Json

