$fragment=(@($lines[629..637]) + @($lines[650..658])) -join [Environment]::NewLine
$script:hvServiceFragment=$fragment
$block=[scriptblock]::Create($fragment)
$cases=@(
 [pscustomobject]@{Id='healthy-local-system';Expected=$true},
 [pscustomobject]@{Id='healthy-system-alias';StartName='NT AUTHORITY\SYSTEM';Expected=$true},
 [pscustomobject]@{Id='wrong-account';StartName='NT AUTHORITY\NetworkService';Expected=$false},
 [pscustomobject]@{Id='stopped';Status='Stopped';Expected=$false},
 [pscustomobject]@{Id='wrong-listener-pid';ListenerPid=54321;Expected=$false},
 [pscustomobject]@{Id='zero-service-pid';ServicePid=0;Expected=$false},
 [pscustomobject]@{Id='missing-exe';Missing='McpServer.Support.Mcp.exe';Expected=$false},
 [pscustomobject]@{Id='missing-manifest';Missing='.mcpservice-deployment.json';Expected=$false},
 [pscustomobject]@{Id='missing-yaml';Missing='appsettings.yaml';Expected=$false},
 [pscustomobject]@{Id='no-listener';NoListener=$true;Expected=$false}
)
$script:hvServiceResults=foreach($case in $cases){
 & {
 param($case,$block)
 function Get-Service {param($Name,$ErrorAction) [pscustomobject]@{Status=$(if($case.Status){$case.Status}else{'Running'})}}
 function Get-CimInstance {param($ClassName,$Filter) [pscustomobject]@{StartName=$(if($case.StartName){$case.StartName}else{'LocalSystem'});ProcessId=$(if($case.PSObject.Properties['ServicePid']){$case.ServicePid}else{12345})}}
 function Test-Path {param($Path) -not ($case.Missing -and $Path.EndsWith($case.Missing))}
 function Get-NetTCPConnection {param($LocalPort,$State,$EA) if(-not $case.NoListener){[pscustomobject]@{OwningProcess=$(if($case.ListenerPid){$case.ListenerPid}else{12345})}}}
 $accepted=$true; $reason=$null
 try {& $block} catch {$accepted=$false; $reason=$_.Exception.Message}
 [pscustomobject]@{Id=$case.Id;Expected=$case.Expected;Accepted=$accepted;Pass=($accepted -eq $case.Expected);Reason=$reason;Scope='Unchanged service/file/listener subfragment only, mock data'}
 } $case $block
}
$script:hvServiceResults|ConvertTo-Json -Depth 4
$parseTokens=$null;$parseProblems=$null
$null=[Management.Automation.Language.Parser]::ParseInput($script:hvVerifyCode,[ref]$parseTokens,[ref]$parseProblems)
$script:hvDocParseEvidence=@($parseProblems|ForEach-Object{[pscustomobject]@{Scope='Windows verify literal code fence';DraftLines='630-662';ErrorId=$_.ErrorId;DraftErrorLine=$_.Extent.StartLineNumber+629;BlockErrorLine=$_.Extent.StartLineNumber;ErrorColumn=$_.Extent.StartColumnNumber;Message=$_.Message}})
$prompt=[IO.File]::ReadAllText('F:\github\McpServer\docs\receipts\hv\20260928T132642Z-setupprompt-draft.prompt.txt')
$script:hvRequestMatches=@()
$stream=[IO.File]::Open($script:hvRollout,[IO.FileMode]::Open,[IO.FileAccess]::Read,[IO.FileShare]::ReadWrite)
$reader=[IO.StreamReader]::new($stream)
try {$script:hvRuntime=$reader.ReadToEnd()} finally {$reader.Dispose()}
$lineNumber=0
foreach($row in $script:hvRuntime -split '\r?\n'){
 $lineNumber++
 if([string]::IsNullOrWhiteSpace($row)){continue}
 try {$evt=$row|ConvertFrom-Json -ErrorAction Stop} catch {continue}
 if($evt.type -eq 'turn_context'){ $script:hvRuntimeProof=[pscustomobject]@{Rollout=$script:hvRollout;Line=$lineNumber;Timestamp=$evt.timestamp;ThreadId=$script:hvSessionMeta.id;TurnId=$evt.payload.turn_id;Model=$evt.payload.model;Effort=$evt.payload.effort;SettingsModel=$evt.payload.collaboration_mode.settings.model;SettingsEffort=$evt.payload.collaboration_mode.settings.reasoning_effort;CliVersion=$script:hvSessionMeta.cli_version}}
 if($evt.type -eq 'response_item' -and $evt.payload.role -eq 'user') {
  foreach($c in $evt.payload.content){
   if($c.text -and $c.text.Trim() -ceq $prompt.Trim()){ $script:hvRequestMatches += $lineNumber }
  }
 }
